UPDATE tianquan_oauth.oauth_grant
SET allowed_scopes = #{po.allowedScopes,
        typeHandler=top.egon.cola.platform.tianquan.shoubing.admin.oauth.dao.OAuthStringListJsonbTypeHandler},
    status = #{po.status},
    resource_version = #{po.resourceVersion},
    version = #{po.version},
    update_user_id = #{po.updateUserId},
    update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId}
  AND id = #{po.id}
  AND client_pk = #{po.clientPk}
  AND resource_server_id = #{po.resourceServerId}
  AND grant_type = #{po.grantType}
  AND version = #{expectedVersion}
  AND deleted_at IS NULL
